/**
 * SyncProvider — app-wide cross-device sync runtime.
 *
 * Holds the single `useSyncEngine` instance so every consumer (Settings
 * controls, edit-triggered auto-push) shares one status machine. On app
 * open, once persistence has booted and an account is connected, it runs
 * one pull-merge-push cycle so a freshly opened device adopts the remote
 * snapshot before normal use. Sync failures stay non-fatal — the local
 * database remains the source of truth.
 */

import {
  createContext,
  type ReactNode,
  useContext,
  useEffect,
  useMemo,
  useRef,
} from "react";

import type { SyncEngine } from "../hooks/sync-engine-types";
import { useSyncEngine } from "../hooks/use-sync-engine";
import { useSyncOnResume } from "../hooks/use-sync-on-resume";
import { useSyncResumeOnGesture } from "../hooks/use-sync-resume-on-gesture";
import type { CloudSyncPort } from "../ports/cloud-sync-port";
import type { SnapshotPort } from "../ports/snapshot-port";

const SyncContext = createContext<SyncEngine | null>(null);

/** The local database snapshot, for readers outside the sync cycle (backup). */
export type SnapshotSource = {
  snapshotPort: SnapshotPort;
  deviceId: string;
  /** Runs after every snapshot import (the match-date heal, design §3.5). */
  afterImport?: () => Promise<void>;
};

const SnapshotSourceContext = createContext<SnapshotSource | null>(null);

export type SyncProviderProps = {
  cloud: CloudSyncPort;
  snapshotPort: SnapshotPort;
  deviceId: string;
  afterImport?: () => Promise<void>;
  children: ReactNode;
};

export const SyncProvider = ({
  cloud,
  snapshotPort,
  deviceId,
  afterImport,
  children,
}: SyncProviderProps) => {
  const engine = useSyncEngine({ cloud, snapshotPort, deviceId, afterImport });
  const bootstrapped = useRef(false);
  const { connected, syncNow } = engine;
  useSyncResumeOnGesture(engine);
  useSyncOnResume(engine);

  useEffect(() => {
    if (bootstrapped.current || !connected) return;
    bootstrapped.current = true;
    void syncNow();
  }, [connected, syncNow]);

  const source = useMemo(
    () => ({ snapshotPort, deviceId, afterImport }),
    [snapshotPort, deviceId, afterImport]
  );

  return (
    <SnapshotSourceContext.Provider value={source}>
      <SyncContext.Provider value={engine}>{children}</SyncContext.Provider>
    </SnapshotSourceContext.Provider>
  );
};

export const useSync = (): SyncEngine => {
  const ctx = useContext(SyncContext);
  if (!ctx) {
    throw new Error("useSync must be used within SyncProvider");
  }
  return ctx;
};

export const useSnapshotSource = (): SnapshotSource => {
  const ctx = useContext(SnapshotSourceContext);
  if (!ctx) {
    throw new Error("useSnapshotSource must be used within SyncProvider");
  }
  return ctx;
};
